public class Main {
    public static void main(String[] args) {
        int a = 6;
        int b = 3;
        System.out.println("a & b: " + (a & b));
        System.out.println("a | b: " + (a | b));
    }
}

public class Main {
    public static void main(String[] args) {
        int num = 12;
        int mult = num << 2;
        int div = num >> 2;
        System.out.println("Original: " + num);
        System.out.println("Multiplied by 4: " + mult);
        System.out.println("Divided by 4: " + div);
    }
}

public class Main {
    public static void main(String[] args) {
        int val = 99;
        int bit = val & 1;
        System.out.println("Value: " + val + " | Parity Bit (1=Odd, 0=Even): " + bit);
    }
}

public class Main {
    public static void main(String[] args) {
        int x = 15, y = 25;
        System.out.println("Before Swap: x=" + x + ", y=" + y);
        x = x ^ y;
        y = x ^ y;
        x = x ^ y;
        System.out.println("After Swap: x=" + x + ", y=" + y);
    }
}

public class Main {
    public static void main(String[] args) {
        int a = 12, b = 10;
        System.out.println("XOR of " + a + " and " + b + ": " + (a ^ b));
    }
}
